import pandas as pd, re, json
from collections import defaultdict

# load logs sample
logs=pd.read_csv('/app/data/test_center_logs.csv')

# load codebooks
codebooks={}
for product,file in [('P1_POWER','/app/data/codebook_P1_POWER.csv'),('P2_CTRL','/app/data/codebook_P2_CTRL.csv'),('P3_RF','/app/data/codebook_P3_RF.csv')]:
    df=pd.read_csv(file)
    entries=[]
    for _,row in df.iterrows():
        kw=[k.strip() for k in str(row['keywords_examples']).split(',') if str(k).strip()!='']
        key_tokens=set()
        for source in [row['keywords_examples'], row['standard_label']]:
            for tok in re.findall(r'[A-Za-z]+\d+|[A-Za-z]+_[A-Za-z0-9]+', str(source)):
                key_tokens.add(tok.upper())
        entries.append({
            'code': row['code'],
            'label': row['standard_label'],
            'category_lv2': row['category_lv2'],
            'station_scope': row['station_scope'],
            'keywords': kw,
            'key_tokens': key_tokens,
        })
    entries=sorted(entries, key=lambda x:x['code'])
    codebooks[product]=entries

# category patterns
cat_patterns={
    'FIXTURE_CONTACT':[r'fixture', r'pogo', r'contact', r'接触不良', r'治具', r'夹具', r'reseat', r'接触差', r'接触不好'],
    'PROBE_WORN':[r'probe worn', r'探针磨损', r'换针', r'replace pin', r'pin worn'],
    'FLASH_FAIL':[r'flash', r'program', r'write fail', r'烧录失败', r'写入失败', r'program fail', r'重烧', r'reflash'],
    'CHECKSUM_FAIL':[r'checksum', r'crc', r'verify fail', r'校验失败'],
    'BOOT_FAIL':[r'boot fail', r'os fail', r'启动不了', r'启动失败', r'cannot boot', r'卡logo', r'stuck', r'进不了系统'],
    'VERSION_MISMATCH':[r'version mismatch', r'版本不符', r'wrong fw', r'下错程序'],
    'LEAKAGE':[r'hipot', r'leakage', r'漏电', r'绝缘'],
    'CURRENT_HIGH':[r'current high', r'icc', r'功耗高', r'静态电流', r'idle current'],
    'HIGH_RES':[r'high_res'],
    'CAL_DATA_FAIL':[r'cal data', r'rf cal', r'校准', r'nv write'],
    'CONNECTOR_WEAR':[r'connector wear', r'sma', r'插拔', r'insertion loss'],
    'CONTAMINATION':[r'contamination', r'residue', r'助焊剂', r'清洗', r'污染'],
    'ESD':[r'esd', r'静电'],
    'PRESSURE_MARK':[r'pressure mark', r'压伤', r'pad damage'],
    'MISSING':[r'missing', r'少件', r'漏装'],
    'REVERSED':[r'reversed', r'polarity', r'反向', r'装反', r'极性'],
    'COLD_SOLDER':[r'cold solder', r'虚焊', r'少锡', r'浮高', r'cold'],
    'SHORT':[r'short', r'短路', r'bridge', r'连锡', r'桥连'],
    'OPEN':[r'open', r'开路'],
}

# compile regex
cat_regex={}
for cat, pats in cat_patterns.items():
    regexes=[]
    for p in pats:
        if re.search(r'[A-Za-z]', p):
            regexes.append(re.compile(p, re.IGNORECASE))
        else:
            regexes.append(re.compile(re.escape(p)))
    cat_regex[cat]=regexes


def pattern_hits(cat, text):
    hits=0
    for rg in cat_regex[cat]:
        if rg.search(text):
            hits+=1
    return hits


def detect_categories(text):
    cats=set()
    t=text
    # OS (open/short) explicit
    if re.search(r'OS\s*\(open\)', t, re.IGNORECASE) or re.search(r'OS\s*open', t, re.IGNORECASE):
        cats.add('OPEN')
    if re.search(r'OS\s*\(short\)', t, re.IGNORECASE) or re.search(r'OS\s*short', t, re.IGNORECASE):
        cats.add('SHORT')
    # main patterns
    for cat in cat_patterns:
        if pattern_hits(cat, t) > 0:
            cats.add(cat)
    # prefer PROBE_WORN over FIXTURE_CONTACT when both
    if 'PROBE_WORN' in cats and 'FIXTURE_CONTACT' in cats:
        cats.remove('FIXTURE_CONTACT')
    return cats

# segmentation by strong separators only
sep_pattern=re.compile(r'(\s+/\s+|\s*&\s*|\s*\+\s*|\s+and\s+|[;；]|\s*\|\s*)')

def split_segments(text):
    segs=[]
    start=0
    for m in sep_pattern.finditer(text):
        end=m.start()
        seg=text[start:end]
        if seg.strip():
            segs.append(seg.strip())
        start=m.end()
    last=text[start:]
    if last.strip():
        segs.append(last.strip())
    return segs

component_required={'OPEN','SHORT','COLD_SOLDER','MISSING','REVERSED'}

# match entry for category

def match_entry_for_category(product, category, segment, station):
    entries=[e for e in codebooks[product] if e['category_lv2']==category]
    if not entries:
        return None, 0.0, 'no_category'
    seg_upper=segment.upper()
    seg_tokens=set(re.findall(r'[A-Za-z]+\d+|[A-Za-z]+_[A-Za-z0-9]+', seg_upper))
    # if component required and no token in segment
    if category in component_required and not seg_tokens:
        return None, 0.25, 'missing_component'
    best=None
    best_score=-1
    best_details=None
    for e in entries:
        kw_matches=0
        for kw in e['keywords']:
            if not kw:
                continue
            if re.search(r'[A-Za-z]', kw):
                if re.search(re.escape(kw), segment, re.IGNORECASE):
                    kw_matches+=1
            else:
                if kw in segment:
                    kw_matches+=1
        token_matches=sum(1 for tok in e['key_tokens'] if tok in seg_upper)
        station_match=0
        if station and isinstance(station, str) and station in str(e['station_scope']).split(';'):
            station_match=1
        score=kw_matches + 2*token_matches + 0.5*station_match
        if score>best_score:
            best_score=score
            best=e
            best_details=(kw_matches, token_matches, station_match)
    if best is None:
        return None, 0.0, 'no_match'
    kw_matches, token_matches, station_match=best_details
    if category in component_required and token_matches==0:
        return None, 0.25, 'missing_component'
    # confidence heuristic
    hits=pattern_hits(category, segment)
    if category in component_required:
        if token_matches>=2:
            conf=0.9
        elif token_matches==1:
            conf=0.78
        else:
            conf=0.25
        if hits>=2:
            conf=min(conf+0.05,0.95)
    else:
        conf=0.55 + min(hits,2)*0.1 + 0.05*station_match
        conf=min(conf,0.9)
    return best, conf, 'ok'

# test with sample raw texts for each product
sample_texts=[
    '治具/探针接触不良，重插后偶尔OK',
    '探针磨损导致接触差，建议换针',
    '烧录失败/写入失败，重烧不稳定',
    '静态电流偏高，疑似短路趋势/器件异常',
    'HiPot 漏电超规，疑似绝缘不良/污染',
    'R152_NET open, suspect cold solder/missing solder / R152_NET 开路，疑似虚焊/少锡 NG',
    'I2C_SDA 开路，疑似虚焊/少锡',
    'OS fail，启动不了，fixture contact unstable, reseat sometimes passes / 治具/探针接触不良，重插后偶尔OK',
    'SW_NODE OS (open) seen NG，治具/探针接触不良，重插后偶尔OK',
    'ANT_FEED 功能不稳，疑似虚焊/浮高',
    '版本不符/下错程序，需确认FW版本',
]

for text in sample_texts:
    segs=split_segments(text)
    print('\nraw:',text)
    for seg in segs:
        cats=detect_categories(seg)
        print(' seg',seg,'cats',cats)
        for cat in sorted(cats) if cats else ['']:
            if cat=='':
                continue
            e,conf,reason=match_entry_for_category('P1_POWER',cat,seg,'FCT')
            print('  ->',cat, (e['code'], e['label']) if e else None, conf, reason)
